import{contextStorage}from"#context/container.js";import{HistoryStateKey}from"#context/keys.js";import{validateHarnessModelMessages}from"#harness/messages.js";import{keptAnnouncements}from"#harness/announcements.js";import{checksSessionEvents}from"#shared/dev-checks.js";import{withoutPromptMeasurement}from"#harness/compaction/engine.js";function changeHistory(e,t){let n=applyChange(e,t);return n!==e&&checksSessionEvents()&&assertAnswersFollowCalls(n.history),n}function applyChange(e,t){if(`append`in t)return t.append.length===0?e:{...e,history:validateHarnessModelMessages([...e.history,...t.append])};if(`extend`in t){let n=validateHarnessModelMessages(t.extend);return assertKeeps(e.history,n),{...e,history:n}}if(`repaired`in t)return{...e,history:validateHarnessModelMessages(t.repaired)};let n=validateHarnessModelMessages(t.rewrite),r=contextStorage.getStore(),i=r?.get(HistoryStateKey);return r!==void 0&&i!==void 0&&r.set(HistoryStateKey,keptAnnouncements(i,n)),{...e,compaction:withoutPromptMeasurement(e.compaction),history:n}}function assertKeeps(e,t){if(!checksSessionEvents())return;let n=0;for(let[r,i]of e.entries()){for(;n<t.length&&!sameMessage(i,t[n]);)n+=1;if(n===t.length)throw Error(`History was extended from ${e.length} to ${t.length} messages without message ${r} (${i.role}). A change to earlier messages is a rewrite: use changeHistory(session, { rewrite }).`);n+=1}}function answersFollowCalls(e){let t=new Set,n=new Set;for(let[r,i]of e.entries())if(typeof i.content!=`string`){for(let e of i.content)if(e.type===`tool-call`&&t.add(e.toolCallId),e.type===`tool-result`){if(!t.has(e.toolCallId))return`History message ${r} answers tool call ${e.toolCallId}, which no earlier message made.`;if(n.has(e.toolCallId))return`History message ${r} answers tool call ${e.toolCallId} a second time.`;n.add(e.toolCallId)}}}function assertAnswersFollowCalls(e){let t=answersFollowCalls(e);if(t!==void 0)throw Error(t)}function sameMessage(e,t){return e===t||JSON.stringify(e)===JSON.stringify(t)}export{changeHistory};